import{_ as s,H as p,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 风起于青萍之末","description":"","frontmatter":{},"headers":[],"relativePath":"DeepSeekHarness前沿工程实践/结束语｜风起于青萍之末.md","filePath":"DeepSeekHarness前沿工程实践/结束语｜风起于青萍之末.md","lastUpdated":1795486719000}'),n={name:"DeepSeekHarness前沿工程实践/结束语｜风起于青萍之末.md"};function i(r,e,o,l,h,_){return p(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="结束语-风起于青萍之末" tabindex="-1">结束语 | 风起于青萍之末 <a class="header-anchor" href="#结束语-风起于青萍之末" aria-label="Permalink to &quot;结束语 | 风起于青萍之末&quot;">​</a></h1><p>你好，我是张嘉熙。</p><p>从 8 月 25 日更新第一讲，到 10 月 26 日完成最后一讲，这套课程陪我们走过了两个月。虽然已经是我在极客时间上的第二套课程，写作和打磨的过程依然充满挑战。感谢你一路学到这里，也欢迎你继续在评论区交流实践中的收获，指出课程中的错漏。</p><p>回顾整门课程，我最想和你分享的，其实有两件事：一是把 dsh 的核心设计和主要逻辑讲清楚；二是这个听上去很玄的“自进化”，落到工程上到底是怎么回事。</p><p>关于第一件事，业界已经有了不少开源的 harness 框架，dsh 也在吸收已有经验的基础上，做出了自己的设计选择。我希望通过课程里的拆解，让你不仅能理解它如何运行，也能进一步思考：这些设计解决了什么问题？换到自己的项目里，哪些值得借鉴，哪些需要调整？</p><p>第二件事，对应的是实战篇最后四讲搭出的那个会自进化的防火墙 Agent。</p><p>一开始，规则库里只有第 18 讲手写的那几条规则。随后，系统读取日志、发现异常、生成候选规则，再通过历史数据回放等方式，评估它拦得准不准、会不会误伤。通过评估的候选规则进入正式规则库；后续发现的漏报，则作为新的证据，进入下一轮改进。</p><p>在这个教学案例里，持续更新的是防火墙的规则库，模型权重并没有改变。我们希望通过这个小小的闭环，让你看到：系统怎样把运行中积累的证据，转化为可以验证、可以保留下来的改进。</p><p>流程说起来不复杂，真正值得花心思的，是其中每一次判断：什么样的异常值得生成规则？怎样证明新规则有效？又怎样避免修好了一个问题，却引入另一个问题？理解这些问题，比记住“自进化”这个名字更重要。</p><p>这也是当下业界正在探索的方向。</p><p>2026 年 7 月 4 日，翁荔发表了博客《Harness Engineering for Self-Improvement》。她提出，近期更可行的自我改进路径，可能先从模型外部的 harness 入手：改进系统组织任务、使用工具、管理上下文和评估结果的方式。</p><p>DeepSeek 的研究员崔添翼随后转发了这篇博客，并表示，Harness 方向和模型方向的自进化，都是很有可能取得成果的方向。</p><p>业界已经在这条路上动起来了。从技能和记忆的积累，到模型与 harness 的联合优化，不同层次的探索正在展开。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>技能的积累与迭代：Anthropic 将 Agent Skills 发布为开放标准，用包含 SKILL.md 文件</span></span></code></pre></div><ul><li><p>及相关资源的文件夹，封装完成任务所需的知识和方法。标准本身不等于自进化，但它为经验的保存、复用和更新提供了载体。当 Agent 能从实践中提炼技能，再根据反馈修订技能时，经验就有机会转化为持续的能力改进。</p></li><li><p>记忆的积累与复用：Nous Research 的 Hermes Agent 支持自动生成技能，并跨会话保存记忆。一次任务中形成的方法、用户表达过的偏好，可以为后续任务提供参考。不过，记</p></li><li><p>得更多并不必然做得更好，哪些信息值得保留、何时需要更新，同样是系统需要解决的问题。</p></li><li><p>模型与 harness 的联合优化：Claude Code、Codex 这类产品让我们看到，Agent 的表现既取决于模型，也取决于围绕模型构建的运行系统。更进一步，研究者正在探索让 harness改进与模型参数更新进入同一个优化循环。翁荔在博客中介绍了这类早期研究：根据任务反馈调整外部机制或模型，让两者共同改进；不过，目前的证据仍需谨慎看待。</p></li></ul><p>这些探索与课程中的防火墙闭环有一个相通之处：让一次任务留下的经验，有机会帮助系统完成下一次任务。</p><p>当然，能形成循环，不等于能持续变好。</p><p>翁荔在博客中也讨论了其中的瓶颈。当前，自我改进循环在反馈客观、结果容易验证的任务上更容易取得成效；面对评估标准模糊、效果需要长期观察的任务，困难仍然很多。上下文和记忆怎样维护，失败经验怎样保留，系统会不会只学会迎合评估指标，都需要继续研究。</p><p>我们课程里的防火墙，也只是一个范围有限的教学闭环。它的价值，在于让这些问题变得具体，让我们有机会亲手尝试、观察结果，并判断一次改动到底有没有带来进步。</p><p>课程结束以后，你可以从一个熟悉的小场景继续尝试：整理一批日志，找出一种反复出现的失败，明确什么算改好，再看看能否把这次改进留下来，帮助下一次运行。如果暂时没有合适的项目，也可以带着这些问题重新审视你正在使用的 Agent：它积累了什么？改变了什么？又凭什么判断自己变好了？</p><p>风起于青萍之末。面对还在快速发展的技术，我们既可以对未来抱有期待，也可以从眼前一个具体、可验证的问题做起。</p><p>感谢你这两个月的陪伴。希望这门课留给你的，除了对 dsh 的理解，还有亲手探索新系统的信心，以及判断它是否真正有效的方法。期待在评论区看到你的实践和发现。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeekHarness%E5%89%8D%E6%B2%BF%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeekHarness%E5%89%8D%E6%B2%BF%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',23)])])}const g=s(n,[["render",i]]);export{c as __pageData,g as default};
